{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be an array of strings")

    required = set(required_symbols)
    by_id = {}
    roots = []
    source_index = {}

    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node missing required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id == "":
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("node symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            raise ValueError("node depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("node removable must be a boolean")
        if not isinstance(utility, (int, float)) or isinstance(utility, bool):
            raise ValueError("node utility must be numeric")

        by_id[node_id] = node
        source_index[node_id] = index
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("tree must contain exactly one root")

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        if parent is None:
            if node["depth"] != 0:
                raise ValueError("root depth must be zero")
            continue
        if parent not in by_id:
            raise ValueError("node parent reference is unknown")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("node depth is inconsistent with parent")
        children[parent].append(node_id)

    seen = set()
    visiting = set()

    def visit(node_id):
        if node_id in visiting:
            raise ValueError("cycle in tree")
        if node_id in seen:
            return
        visiting.add(node_id)
        for child_id in children[node_id]:
            visit(child_id)
        visiting.remove(node_id)
        seen.add(node_id)

    root_id = roots[0]
    visit(root_id)
    if len(seen) != len(nodes):
        raise ValueError("tree is not connected")

    represented = {node["symbol"] for node in nodes}
    if not required.issubset(represented):
        raise ValueError("required symbol is not represented")

    retained = {node["id"] for node in nodes}
    removed = []
    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    for node in candidates:
        node_id = node["id"]
        if node_id == root_id:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        next_retained = retained - {node_id}
        next_symbols = {by_id[retained_id]["symbol"] for retained_id in next_retained}
        if required.issubset(next_symbols):
            retained = next_retained
            removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
